local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local KTool = CS.Engine.Lib.KTool
local XLuaUtils = CS.Engine.Lib.XLuaUtils
local UIEventProxy = CS.Engine.UI.UIEventProxy
local UIModule = CS.Engine.UI.UIModule
local ImageAlterable = CS.Engine.UI.ImageAlterable
local Image = CS.UnityEngine.UI.Image

------------ import ------------
---@type TrailBattleMgr
local TrailBattleMgr = import('Game.TrailBattle.TrailBattleMgr')

------------ import ------------

------------ define ------------
local ICON_PATH = 'uiatlas/trailstage/competition_common_ico_rank'
------------ define ------------

---@class TrailPopupDialog
---@field PreviewButton                    UnityEngine.RectTransform
---@field ScoreText                        UnityEngine.UI.Extensions.TextPic
---@field PreviewNameText                Engine.I18N.I18NText
---@field StateText                        UnityEngine.UI.Text
---@field StateIcon                        UnityEngine.RectTransform
---@field DescriptionText                UnityEngine.UI.Text
---@field LvIcon                            UnityEngine.RectTransform
---@field LevelText                        UnityEngine.UI.Text
---@field RewardText                        UnityEngine.UI.Text
---@field NameText                        Engine.I18N.I18NText
---@field CommonButtonOK                    UnityEngine.RectTransform
---@field FirstEntry                        UnityEngine.RectTransform
---@field ScorePreviewNode                UnityEngine.RectTransform
---@field EntryState                        UnityEngine.RectTransform
---@field EntryFirstTimeNode                UnityEngine.RectTransform
local TrailPopupDialog = Class("TrailPopupDialog")

function TrailPopupDialog:__init()
end

function TrailPopupDialog:__delete()
    self.controller = nil
end

function TrailPopupDialog:Awake()
    local trailBattleMgr = TrailBattleMgr:GetInstance()
    local argument = self.controller.Argument.parameters
    if argument and argument.type then
        if argument.type == TrailBattleMgr.CONSTANTS.POPUP_TYPE.FIRST_ENTRY then

            local segment = trailBattleMgr:GetMySegment()
            local segmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(segment)
            self.LevelText.text = segmentVo.name

            KTool.SetActive(self.EntryState.gameObject, false)
            KTool.SetActive(self.ScorePreviewNode.gameObject, false)
            UIEventProxy.Create(self.CommonButtonOK.gameObject).onPointerClick = function(eventData)
                UIModule.BackDialog()
            end
        elseif argument.type == TrailBattleMgr.CONSTANTS.POPUP_TYPE.SEGMENT_CHANGE then
            ----段位变化
            KTool.SetActive(self.EntryState.gameObject, true)
            KTool.SetActive(self.FirstEntry.gameObject, false)
            KTool.SetActive(self.ScorePreviewNode.gameObject, false)
            UIEventProxy.Create(self.CommonButtonOK.gameObject).onPointerClick = function(eventData)
                UIModule.BackDialog()
            end

            ---更新段位图标与段位名称
            KTool.GetOrAddComponent(self.StateIcon.gameObject, typeof(ImageAlterable)):LoadSprite(
                    string.format('%s_%d.png', ICON_PATH, 1)
            )
            local segment, lastSegment = argument.segment, argument.lastSegment
            KTool.SetActive(self.EntryState.gameObject, true)
            KTool.SetActive(self.FirstEntry.gameObject, false)
            KTool.SetActive(self.EntryFirstTimeNode.gameObject, true)
            KTool.SetActive(self.ScorePreviewNode.gameObject, false)

            local segmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(segment)
            self.NameText.text = localize('根据上一期的排名，调查官本期被划分在')
            if segmentVo then
                self.LevelText.text = segmentVo.name
            end
            KTool.GetOrAddComponent(self.LvIcon.gameObject, typeof(ImageAlterable)):LoadSprite(
                    trailBattleMgr:GetSegmentIconPath(segment, true)
            )
            local rank = checkInt(argument.rank)

            if segmentVo.upGrade ~= 0 then
                ---存在晋级区间
                local low, upper = checkInt(segmentVo.upGrade[1]), checkInt(segmentVo.upGrade[2])
                if rank >= low and rank <= upper then
                    ---晋级
                    self.StateText.text = localize('已晋级')
                    ---@type UnityEngine.UI.Image
                    local image = KTool.GetComponent(self.StateText.transform.parent.gameObject, typeof(Image))
                    if image then
                        image.color = XLuaUtils.HexToColor(TrailBattleMgr.CONSTANTS.COLORS.LEVEL_UP)
                    end
                    KTool.GetOrAddComponent(self.StateIcon.gameObject, typeof(ImageAlterable)):LoadSprite(
                            trailBattleMgr:GetRankGroupIconPath(TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.UP_BUTTON)
                    )
                    self.RewardText.text = localize('晋级奖励已发放至邮箱')
                end
            end
            if segmentVo.keepGrade ~= 0 then
                ---存在晋级区间
                local low, upper = checkInt(segmentVo.keepGrade[1]), checkInt(segmentVo.keepGrade[2])
                if rank >= low and rank <= upper then
                    ---保级
                    ---@type UnityEngine.UI.Image
                    local image = KTool.GetComponent(self.StateText.transform.parent.gameObject, typeof(Image))
                    if image then
                        image.color = XLuaUtils.HexToColor(TrailBattleMgr.CONSTANTS.COLORS.LEVEL_STAY)
                    end
                    KTool.GetOrAddComponent(self.StateIcon.gameObject, typeof(ImageAlterable)):LoadSprite(
                            trailBattleMgr:GetRankGroupIconPath(TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.STAY_BUTTON)
                    )
                    self.RewardText.text = localize('晋级奖励已发放至邮箱')
                end
            end
            if segmentVo.downGrade ~= 0 then
                ---存在晋级区间
                local low, upper = checkInt(segmentVo.downGrade[1]), checkInt(segmentVo.downGrade[2])
                if rank >= low and rank <= upper then
                    ---降级
                    ---@type UnityEngine.UI.Image
                    local image = KTool.GetComponent(self.StateText.transform.parent.gameObject, typeof(Image))
                    if image then
                        image.color = XLuaUtils.HexToColor(TrailBattleMgr.CONSTANTS.COLORS.LEVEL_DOWN)
                    end
                    KTool.GetOrAddComponent(self.StateIcon.gameObject, typeof(ImageAlterable)):LoadSprite(
                            trailBattleMgr:GetRankGroupIconPath(TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.DOWN_BUTTON)
                    )
                    if rank == 0 then
                        self.RewardText.text = localize('由于调查官未完成挑战参与评分，无法获得奖励')
                    else
                        self.RewardText.text = localize('晋级奖励已发放至邮箱')
                    end
                end
            end
        else
            ---分等等级变化
            KTool.SetActive(self.EntryState.gameObject, false)
            KTool.SetActive(self.FirstEntry.gameObject, false)
            KTool.SetActive(self.EntryFirstTimeNode.gameObject, false)
            KTool.SetActive(self.ScorePreviewNode.gameObject, true)
            UIEventProxy.Create(self.PreviewButton.gameObject).onPointerClick = function(eventData)
                UIModule.BackDialog()
            end

            local rank, lastRank = argument.rank, argument.lastRank
            if lastRank == 0 and rank > 0 then
                ---首次结算
                self.PreviewNameText.text = localize('当前排名')
                ---@type UnityEngine.RectTransform
                local rectTransform = KTool.GetComponent(self.ScoreText.gameObject, typeof(CS.UnityEngine.RectTransform))
                rectTransform.anchoredPosition = Vector2.New(-14.9, 20)
                self.ScoreText.text = string.format('<size=20>No.</size>%d', rank)
            else
                if rank > lastRank then
                    ---排名上升
                    self.PreviewNameText.text = localize('排名下降')
                else
                    self.PreviewNameText.text = localize('排名上升')
                end
                self.ScoreText.text = string.format('<size=20>No.</size>%d _to_ <size=20>No.</size>%d', lastRank, rank)
            end
        end
    end
end

function TrailPopupDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

    end))
    return coWait
end

function TrailPopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailPopupDialog